__vfs['core/env.lua'] = function(...)
-- core/env.lua — Java/Android environment gate
-- Loaded before any imports. Calls os.exit() on failure; no return value.

local function fail(msg)
    if gg.alert("Environment check failed!\n\n" .. msg .. "\n\nUse GG: ME by Vekendian.", "Get GG: ME", "OK") == 1 then
        gg.copyText("https://github.com/vekendianorg/me/releases")
    end
    os.exit()
end

if type(luajava)  ~= "table"    then fail("LuaJava not detected.") end
if type(import)   ~= "function" then fail("import() unavailable.") end
if not pcall(function() import("java.lang.String") end)  then fail("Core Java classes unavailable.") end
if not pcall(function() import("android.os.Build") end)  then fail("Android API unavailable.") end

do
    local V = import("android.os.Build$VERSION")
    if V.SDK_INT < 21 then
        fail(("Android 5.0+ (API 21) required. Detected API %d."):format(V.SDK_INT))
    end
end

local required = {
    "android.ext.Tools", "android.ext.rx", "android.ext.Script",
    "android.ext.Config", "android.ext.MainService",
    "org.vekendian.Crypto", "org.vekendian.Ui", "org.vekendian.Zip",
    "org.vekendian.Shell"
}
local missing = {}
for _, cls in ipairs(required) do
    if not pcall(function() luajava.bindClass(cls) end) then
        missing[#missing + 1] = cls
    end
end
if #missing > 0 then fail("Missing classes:\n" .. table.concat(missing, "\n")) end

end

__vfs['core/engines/arch.lua'] = function(...)
-- core/engines/arch.lua — Architecture detection + chain-based version resolution
-- Sets globals: DEVICE_ARCH, BaseLib, aobs, offsets
-- Depends on: loadModule, memory (already loaded), gg, showDialog, LOG,
--             DEFAULT_ARCH (set in main.lua)

-- ── Architecture detection ────────────────────────────────────────────────────

-- ELF e_machine values read from libcocos2dcpp.so at offset +0x10 (DWORD).
local ARCH_MAP = {
    [11993091] = "arm64-v8a",
    [4063235]  = "x86_64",
    [2621443]  = "armeabi-v7a",
    [196611]   = "x86",
}

local lib_ranges = gg.getRangesList("libcocos2dcpp.so")
if #lib_ranges > 0 then
    local elf_machine = gg.getValues({ { address = lib_ranges[1].start + 0x10, flags = gg.TYPE_DWORD } })[1]
    DEVICE_ARCH = ARCH_MAP[elf_machine and tonumber(elf_machine.value)] or "unknown"
    BaseLib     = lib_ranges[1].start
    LOG.info("Arch", string.format("Lib ranges: %d | BaseLib: 0x%X | e_machine: %s → %s",
        #lib_ranges, BaseLib, tostring(elf_machine and elf_machine.value), DEVICE_ARCH))
else
    LOG.warn("Arch", "libcocos2dcpp.so not found in ranges list")
end

if DEVICE_ARCH == "unknown" then
    LOG.warn("Arch", "Architecture unrecognized — ELF e_machine not in ARCH_MAP")
    showDialog(T("arch.warning_title"),
        T("arch.unknown_arch_msg"),
        T("common.proceed_anyway"))
end

if DEVICE_ARCH ~= "arm64-v8a" then
    LOG.warn("Arch", "Non-primary architecture: " .. DEVICE_ARCH .. " — lib patches may not work")
    showDialog(T("arch.warning_title"),
        T("arch.non_primary_arch_msg", DEVICE_ARCH),
        T("common.proceed_anyway"))
end


-- ── Version comparison ────────────────────────────────────────────────────────

-- Splits "1.73.5" into { 1, 73, 5 }.
local function parse_version(v)
    local ma, mi, pa = v:match("(%d+)%.(%d+)%.(%d+)")
    if not ma then return nil end
    return { tonumber(ma), tonumber(mi), tonumber(pa) }
end

-- Returns -1, 0, or 1 — same contract as C's strcmp.
local function cmp_version(a, b)
    for i = 1, 3 do
        if     a[i] < b[i] then return -1
        elseif a[i] > b[i] then return  1
        end
    end
    return 0
end


-- ── Chain resolution ──────────────────────────────────────────────────────────
--
-- The manifest supplies an ordered `chain` array per arch.  Each entry is:
--
--   { version = "1.73.3", file = "data/arm64-v8a/1.73.3.lua", full = true }
--
-- `full = true`  → the file is a complete baseline (aobs + offsets).
--                  The engine resets its accumulated state before applying it.
--
-- `full = false` (or absent) → the file is a diff.  Only the keys present
--                  inside `aobs` / `offsets` replace the matching keys in the
--                  accumulated state; everything else is kept as-is.
--
-- The engine walks the chain from the beginning up to (and including) the
-- closest entry whose version is ≤ the device's game version, accumulating
-- changes as it goes.  This means:
--
--   • Users on 1.73.3 see exactly the 1.73.3 data.
--   • Users on 1.73.5 see 1.73.3 base + whatever 1.73.5 changed.
--   • Users on 1.74.0 (a new era) see only the fresh 1.74.0 baseline because
--     that entry is marked `full = true`, resetting the accumulated state.
--   • Users on an unknown future version (e.g. 1.75.0) see the last known
--     entry and get a "running on newer version" warning — same behaviour as
--     the old default_base fallback, but now it's the most recent data rather
--     than the oldest.

local function resolve_chain(chain, device_ver_t)
    -- `state` is what we accumulate across the chain walk.
    local state = { aobs = {}, offsets = {} }
    -- `last_applied` tracks the highest version we successfully merged into
    -- state, for the "running on newer game" warning message.
    local last_applied = nil

    for _, entry in ipairs(chain) do
        local entry_ver_t = parse_version(entry.version)
        if not entry_ver_t then
            LOG.warn("Arch", "Chain entry has unparseable version: " .. tostring(entry.version) .. " — skipped")
            goto continue
        end

        -- Stop walking once the chain passes the device version.
        if cmp_version(entry_ver_t, device_ver_t) > 0 then
            LOG.info("Arch", "Chain walk stopped before " .. entry.version .. " (device is older)")
            break
        end

        -- Load the file.
        local ok, data = pcall(loadModule, entry.file)
        if not ok or type(data) ~= "table" then
            LOG.error("Arch", "Failed to load chain entry " .. entry.version .. " (" .. tostring(entry.file) .. "): " .. tostring(data))
            goto continue
        end

        LOG.info("Arch", string.format(
            "Chain entry %s loaded | aobs=%s  offsets=%s  full=%s",
            entry.version,
            type(data.aobs)    == "table" and tostring(#(function() local n=0; for _ in pairs(data.aobs)    do n=n+1 end; return n end)()) .. " groups" or "nil",
            type(data.offsets) == "table" and tostring(#(function() local n=0; for _ in pairs(data.offsets) do n=n+1 end; return n end)()) .. " keys"   or "nil",
            tostring(entry.full)))

        -- A full baseline resets accumulated state before merging.
        if entry.full then
            LOG.info("Arch", "Chain: full baseline reset at " .. entry.version)
            state = { aobs = {}, offsets = {} }
        end

        -- Merge aobs: per-group keys replace existing ones.
        if type(data.aobs) == "table" then
            for k, v in pairs(data.aobs) do
                state.aobs[k] = v
                LOG.dbg("Arch", "  aobs[" .. k .. "] merged")
            end
        else
            LOG.warn("Arch", "  No aobs table in " .. entry.version .. " — patch features will be unavailable")
        end

        -- Merge offsets: per-key replacement.
        if type(data.offsets) == "table" then
            for k, v in pairs(data.offsets) do
                state.offsets[k] = v
                LOG.dbg("Arch", "  offsets[" .. k .. "] = 0x" .. string.format("%X", v))
            end
        else
            LOG.warn("Arch", "  No offsets table in " .. entry.version)
        end

        last_applied = entry.version
        LOG.info("Arch", "Chain: applied " .. entry.version .. (entry.full and " [full]" or " [diff]"))

        ::continue::
    end

    return state, last_applied
end


-- ── Manifest loading ──────────────────────────────────────────────────────────

local manifest    = loadModule("data/manifest.lua")
local pkg_version = gg.getTargetInfo().versionName
LOG.info("Arch", "Game version: " .. tostring(pkg_version) .. " | Arch: " .. tostring(DEVICE_ARCH))

if type(pkg_version) ~= "string" then
    LOG.fatal("Arch", "pkg_version is not a string: " .. type(pkg_version))
    showDialog(T("common.warning"), T("arch.unknown_version_msg"), T("common.ok"))
    os.exit(0)
end

local device_ver_t = parse_version(pkg_version)
if not device_ver_t then
    LOG.fatal("Arch", "Could not parse game version: " .. pkg_version)
    showDialog(T("common.warning"), T("arch.unknown_version_msg"), T("common.ok"))
    os.exit(0)
end

-- Resolve which arch's tree to use.
local arch_t = manifest[DEVICE_ARCH]
if not arch_t then
    LOG.warn("Arch", string.format(
        "No manifest entry for '%s' — falling back to '%s' (lib patches likely won't match)",
        DEVICE_ARCH, DEFAULT_ARCH))
    arch_t = manifest[DEFAULT_ARCH]
end

if not arch_t or not arch_t.chain or #arch_t.chain == 0 then
    LOG.fatal("Arch", "Manifest missing or empty chain for resolved arch — cannot continue")
    showDialog(T("common.warning"), T("arch.no_base_data_msg"), T("common.ok"))
    os.exit(0)
end

-- Walk the chain.
local resolved, last_applied = resolve_chain(arch_t.chain, device_ver_t)

-- Warn if the game version is newer than anything in the chain.
local last_chain_ver_t = parse_version(arch_t.chain[#arch_t.chain].version)
if last_chain_ver_t and cmp_version(device_ver_t, last_chain_ver_t) > 0 then
    LOG.warn("Arch", string.format(
        "Game v%s is newer than the latest chain entry (%s) — using best available data",
        pkg_version, arch_t.chain[#arch_t.chain].version))
    showDialog(T("arch.warning_title"),
        T("arch.newer_version_msg", pkg_version, arch_t.chain[#arch_t.chain].version),
        T("common.proceed_anyway"))
end

local function count(t)
    local n = 0
    for _ in pairs(t) do n = n + 1 end
    return n
end

aobs    = resolved.aobs
offsets = resolved.offsets

LOG.info("Arch", string.format(
    "Data resolved | chain_applied=%s | aobs=%d groups | offsets=%d entries",
    tostring(last_applied), count(aobs), count(offsets)))

end

__vfs['core/engines/crash_handler.lua'] = function(...)
--[[
  core/engines/crash_handler.lua — Structured error capture layer

  Keeps two in-memory ring buffers that feed the Console tab:
    • crashes — explicit captures with a traceback (scheduler task failures,
                feature-module load failures, guarded calls). Cap: 50.
    • logs    — every LOG line (all levels: INFO/DEBUG/WARN/ERROR/FATAL),
                mirrored here via a sink installed into main.lua's logger. Cap: 250.

  Also provides loadFeature(), a NON-FATAL loader for feature/core modules: a
  crash while loading one feature is captured and a safe stub is returned, so
  the rest of the UI keeps working instead of the whole script exiting.

  Sets global: CrashHandler  (assigned by main.lua from this file's return)
  Installs:    __log_sink     (read by the logger in main.lua)

  Globals used: loadModule, LOG, os.
]]

-- Caps are loaded lazily on first getCaps()/setCaps() call because
-- memory is not yet initialized when this module loads (crash_handler
-- loads at line ~250 in main.lua; memory loads at line ~461).
local MAX_CRASHES = 50
local MAX_LOGS    = 250
local _capsLoaded = false

local function ensureCapsLoaded()
    if _capsLoaded then return end
    _capsLoaded = true
    if memory then
        local saved = memory:load_global("console_caps") or {}
        MAX_CRASHES = saved.crashes or MAX_CRASHES
        MAX_LOGS    = saved.logs    or MAX_LOGS
    end
end

local crashes = {}   -- ring buffer (oldest first)
local logs    = {}   -- ring buffer (oldest first)

local function push(ring, max, entry)
    ring[#ring + 1] = entry
    if #ring > max then table.remove(ring, 1) end
end

-- Trim an existing ring buffer to a new (smaller) cap immediately.
local function trimTo(ring, max)
    while #ring > max do table.remove(ring, 1) end
end

-- Wall-clock stamp. os.date is available in this environment.
local function stamp()
    local ok, s = pcall(os.date, "%H:%M:%S")
    return ok and s or "??:??:??"
end

local function trim(s) return (tostring(s):gsub("%s+$", "")) end

local CrashHandler = {}

-- Record a crash. `traceback` is optional but strongly preferred.
function CrashHandler.capture(tag, message, traceback)
    local entry = {
        kind      = "crash",
        ts        = stamp(),
        tag       = tostring(tag or "?"),
        message   = trim(message),
        traceback = traceback and tostring(traceback) or nil,
    }
    push(crashes, MAX_CRASHES, entry)
    -- Mirror to the debug log for file persistence. The "[CRASH]" sentinel
    -- lets onLog skip it so it isn't double-listed in the logs ring.
    if LOG then pcall(LOG.error, entry.tag, "[CRASH] " .. entry.message) end
    return entry
end

-- LOG sink installed into main.lua's _write. Keeps every level; the Console
-- colors them by severity. Crash mirrors (tagged "[CRASH]") are skipped so they
-- aren't double-listed alongside the crashes ring.
function CrashHandler.onLog(level, tag, message)
    local lv = trim(level)
    if type(message) == "string" and message:find("[CRASH]", 1, true) then return end
    push(logs, MAX_LOGS, {
        kind    = "log",
        ts      = stamp(),
        level   = lv,
        tag     = tostring(tag or ""),
        message = tostring(message or ""),
    })
end

-- Run fn(...) guarded; capture (with traceback) on error.
-- Returns ok, result (result is nil on failure).
function CrashHandler.guard(tag, fn, ...)
    local args, n = { ... }, select("#", ...)
    local ok, res = xpcall(
        function() return fn(table.unpack(args, 1, n)) end,
        function(e) return (debug and debug.traceback) and debug.traceback(tostring(e), 2) or tostring(e) end
    )
    if not ok then
        CrashHandler.capture(tag, (tostring(res):match("^[^\n]*")) or res, res)
        return false, nil
    end
    return true, res
end

-- Non-fatal feature/core module loader. On failure, captures the crash and
-- returns a stub table: indexing any key yields a no-op function that still
-- invokes a trailing callback argument (cb/done), so the UI never hard-locks.
local STUB = setmetatable({}, {
    __index = function()
        return function(...)
            local a = { ... }
            local last = a[#a]
            if type(last) == "function" then pcall(last, "unavailable") end
        end
    end,
})

function CrashHandler.loadFeature(name)
    local mod, err = loadModule(name, true)  -- soft = non-fatal
    if mod == nil then
        CrashHandler.capture("loadFeature", "Failed to load " .. tostring(name) .. ": " .. tostring(err), err)
        return STUB
    end
    return mod
end

-- ── Accessors for the Console tab ─────────────────────────────────────────────

function CrashHandler.getCrashes() return crashes end
function CrashHandler.getLogs()    return logs end
function CrashHandler.counts()     return #crashes, #logs end
function CrashHandler.isEmpty()    return #crashes == 0 and #logs == 0 end

function CrashHandler.getCaps()
    ensureCapsLoaded()
    return MAX_CRASHES, MAX_LOGS
end

-- Update caps at runtime (called from Settings). Immediately trims existing
-- buffers so they don't exceed the new cap.
function CrashHandler.setCaps(crashCap, logCap)
    ensureCapsLoaded()
    -- nil means "keep the current value" — lets callers update only one cap.
    crashCap = math.max(5, math.min(500,  tonumber(crashCap) or MAX_CRASHES))
    logCap   = math.max(5, math.min(2000, tonumber(logCap)   or MAX_LOGS))
    MAX_CRASHES = crashCap
    MAX_LOGS    = logCap
    trimTo(crashes, MAX_CRASHES)
    trimTo(logs,    MAX_LOGS)
    memory:save_global("console_caps", { crashes = MAX_CRASHES, logs = MAX_LOGS })
    LOG.info("CrashHandler", string.format("Caps updated: crashes=%d  logs=%d", MAX_CRASHES, MAX_LOGS))
end

function CrashHandler.clear()
    for i = #crashes, 1, -1 do crashes[i] = nil end
    for i = #logs, 1, -1 do logs[i] = nil end
end

-- Flat text dump for the Console "Copy all" button.
function CrashHandler.formatAll()
    local out = {}
    out[#out + 1] = "===== VOID Console ====="
    out[#out + 1] = "crashes=" .. #crashes .. "  logs=" .. #logs
    out[#out + 1] = ""
    out[#out + 1] = "----- CRASHES & ERRORS -----"
    if #crashes == 0 then out[#out + 1] = "(none)" end
    for _, e in ipairs(crashes) do
        out[#out + 1] = string.format("[%s] [%s] %s", e.ts, e.tag, e.message)
        if e.traceback then out[#out + 1] = e.traceback end
        out[#out + 1] = ""
    end
    out[#out + 1] = "----- LOGS -----"
    if #logs == 0 then out[#out + 1] = "(none)" end
    for _, e in ipairs(logs) do
        out[#out + 1] = string.format("[%s] [%s] [%s] %s", e.ts, e.level, e.tag, e.message)
    end
    return table.concat(out, "\n")
end

-- Install the logger sink so WARN+ lines start flowing in immediately.
__log_sink = CrashHandler.onLog

return CrashHandler

end

__vfs['core/engines/memory.lua'] = function(...)
--[[
  Persistent memory handler module
  Manages saving and loading of game state data.

  Two storage scopes:
    Process-scoped  (save / load)             — tied to the current target PID.
                                                Data is wiped automatically when
                                                the process changes (game restart).
    Global-scoped   (save_global / load_global) — PID-independent; survives
                                                across restarts. Intended for user
                                                preferences such as UI colors that
                                                should never be cleared by a process
                                                switch.
]]

-- NOTE: File is imported globally in main.lua; no local import needed here.

-- Shared serializer used by both save scopes.
-- Handles tables (recursively), strings, and scalar values.
local function serialize(v)
    if type(v) == "table" then
        local s = "{"
        for k, val in pairs(v) do
            local key = type(k) == "number" and "[" .. k .. "]" or string.format("[%q]", k)
            s = s .. key .. "=" .. serialize(val) .. ","
        end
        return s .. "}"
    elseif type(v) == "string" then
        return string.format("%q", v)
    else
        return tostring(v)
    end
end

local memory = {
    -- ── Process-scoped helpers ────────────────────────────────────────────────

    ---Checks whether the current GG session is still attached to the same PID.
    ---Clears all process-scoped data automatically when the process changes.
    ---@return boolean True if session is valid (same PID), false if it changed.
    _check_session = function(self)
        local target = gg.getTargetInfo()
        if not target then return false end

        local current_pid = target.pid
        local pid_file    = gg.FILES_DIR .. "/" .. target.packageName

        local old_pid
        local f = io.open(pid_file, "r")
        if f then
            old_pid = tonumber(f:read("*all"))
            f:close()
        end

        if old_pid ~= current_pid then
            self:clear_all()
            f = io.open(pid_file, "w")
            if f then
                f:write(tostring(current_pid))
                f:close()
            end
            return false
        end
        return true
    end,

    ---Saves data to process-scoped persistent storage.
    ---Keyed by package name + PID; automatically invalidated on process change.
    ---@param id   string Unique identifier (e.g. "gamestatus", "toggle_states")
    ---@param data any    Data to persist (tables are serialized recursively)
    ---@return boolean True if the write succeeded
    save = function(self, id, data)
        self:_check_session()
        local target = gg.getTargetInfo()
        if not (target and data ~= nil) then
            LOG.warn("Memory", "save() skipped — no target or nil data | id=" .. tostring(id))
            return false
        end

        local file_path = gg.FILES_DIR .. "/" .. target.packageName .. "-memoryHandlers-" .. id
        local f = io.open(file_path, "w")
        if f then
            f:write("return " .. serialize(data))
            f:close()
            LOG.dbg("Memory", "Saved: " .. id)
            return true
        end
        LOG.error("Memory", "save() failed to open file for: " .. id)
        return false
    end,

    ---Loads previously saved process-scoped data.
    ---Returns nil if the session changed or the data file does not exist.
    ---@param id string Unique identifier for the data to load
    ---@return any Loaded data, or nil
    load = function(self, id)
        if not self:_check_session() then
            LOG.dbg("Memory", "load() skipped — session changed | id=" .. tostring(id))
            return nil
        end

        local target = gg.getTargetInfo()
        if not target then return nil end
        local file_path = gg.FILES_DIR .. "/" .. target.packageName .. "-memoryHandlers-" .. id
        local chunk = loadfile(file_path)
        if chunk then
            LOG.dbg("Memory", "Loaded: " .. id)
        else
            LOG.dbg("Memory", "No cache for: " .. id)
        end
        return chunk and chunk() or nil
    end,

    ---Deletes a single process-scoped cache entry by id.
    ---Safe to call even if the entry does not exist.
    ---@param id string Unique identifier to delete
    ---@return boolean True if the file was deleted, false if it didn't exist or failed
    delete = function(self, id)
        local target = gg.getTargetInfo()
        if not target then
            LOG.warn("Memory", "delete() skipped — no target | id=" .. tostring(id))
            return false
        end
        local file_path = gg.FILES_DIR .. "/" .. target.packageName .. "-memoryHandlers-" .. id
        local ok = os.remove(file_path)
        if ok then
            LOG.info("Memory", "Deleted: " .. id)
        else
            LOG.dbg("Memory", "delete() — file not found or already gone: " .. id)
        end
        return ok ~= nil
    end,

    ---Deletes all process-scoped data files for the current package.
    ---Called automatically when a PID change is detected.
    ---@return nil
    clear_all = function(self)
        local target = gg.getTargetInfo()
        if not target then return end
        local prefix    = target.packageName .. "-memoryHandlers-"
        local directory = File(gg.FILES_DIR)
        local files     = directory:listFiles()
        local count = 0
        if files then
            for i = 1, #files do
                local file = files[i]
                if file:getName():find(prefix, 1, true) == 1 then
                    file:delete()
                    count = count + 1
                end
            end
        end
        LOG.info("Memory", "clear_all() removed " .. tostring(count) .. " cache files")
    end,

    -- ── Global-scoped helpers ─────────────────────────────────────────────────

    ---Saves data to global persistent storage.
    ---Not tied to any process or package; survives game restarts and
    ---process switches. Intended for user preferences (UI colors, etc.).
    ---@param id   string Unique identifier (e.g. "ui_prefs")
    ---@param data any    Data to persist (tables are serialized recursively)
    ---@return boolean True if the write succeeded
    save_global = function(self, id, data)
        if data == nil then return false end
        local file_path = gg.FILES_DIR .. "/void-global-" .. id
        local f = io.open(file_path, "w")
        if f then
            f:write("return " .. serialize(data))
            f:close()
            return true
        end
        return false
    end,

    ---Loads previously saved global data.
    ---Returns nil if the file does not exist or cannot be parsed.
    ---@param id string Unique identifier for the data to load
    ---@return any Loaded data, or nil
    load_global = function(self, id)
        local file_path = gg.FILES_DIR .. "/void-global-" .. id
        local chunk = loadfile(file_path)
        return chunk and chunk() or nil
    end,

    ---Deletes a single global cache entry by id.
    ---Safe to call even if the entry does not exist.
    ---@param id string Unique identifier to delete
    ---@return boolean True if the file was deleted, false if it didn't exist or failed
    delete_global = function(self, id)
        local file_path = gg.FILES_DIR .. "/void-global-" .. id
        local ok = os.remove(file_path)
        if ok then
            LOG.info("Memory", "Deleted global: " .. id)
        else
            LOG.dbg("Memory", "delete_global() — file not found or already gone: " .. id)
        end
        return ok ~= nil
    end,

    ---Deletes all global cache files (void-global-* prefix).
    ---Use with caution — this wipes all persisted user preferences and global state.
    ---@return nil
    clear_all_global = function(self)
        local prefix    = "void-global-"
        local directory = File(gg.FILES_DIR)
        local files     = directory:listFiles()
        local count = 0
        if files then
            for i = 1, #files do
                local file = files[i]
                if file:getName():find(prefix, 1, true) == 1 then
                    file:delete()
                    count = count + 1
                end
            end
        end
        LOG.info("Memory", "clear_all_global() removed " .. tostring(count) .. " global files")
    end,
}

return memory

end

__vfs['core/engines/patches.lua'] = function(...)
-- core/engines/patches.lua — Memory patch engine + architecture-aware module helper
-- Exposes globals: addArchModule
-- Depends on: memory, scheduler, gg (all loaded before this file)

-- ── Internal helpers ──────────────────────────────────────────────────────────

---Parses a hex byte string into a flat array of TYPE_BYTE write entries.
---@param addr   number  Base address to write to
---@param hex_str string  e.g. "h 00 94 99 52 C0 03 5F D6"
---@return table writes
local function hex_to_writes(addr, hex_str)
    local writes = {}
    local clean  = hex_str:gsub("^h%s*", ""):gsub("%s+", "")
    local offset = 0
    for i = 1, #clean, 2 do
        writes[#writes + 1] = {
            address = addr + offset,
            flags   = gg.TYPE_BYTE,
            value   = tonumber(clean:sub(i, i + 1), 16),
        }
        offset = offset + 1
    end
    return writes
end

---Reads bytes at (base + check.offset) and compares against allowed values.
---@param base     number
---@param patterns table
---@return boolean
local function verify_pattern(base, patterns)
    for _, check in ipairs(patterns) do
        local addr = base + check.offset
        local len  = #check.valid[1]:gsub("^h%s*", ""):gsub("%s+", "") / 2

        local query = {}
        for i = 0, len - 1 do
            query[#query + 1] = { address = addr + i, flags = gg.TYPE_BYTE }
        end

        local read = gg.getValues(query)
        if not read then return false end

        local hex = {}
        for _, v in ipairs(read) do
            hex[#hex + 1] = string.format("%02X", v.value & 0xFF)
        end

        local current = "h " .. table.concat(hex, " ")

        local ok = false
        for _, expected in ipairs(check.valid) do
            if current == expected then
                ok = true
                break
            end
        end

        if not ok then return false end
    end

    return true
end

---Returns true if `t` is a flat array of patch entries (each entry has a `scan` key).
---@param t table
---@return boolean
local function is_patch_list(t)
    return type(t) == "table" and type(t[1]) == "table" and t[1].scan ~= nil
end


-- ── Patch engine ──────────────────────────────────────────────────────────────

---Applies or reverts a set of memory patches.
---Addresses are resolved via AoB scan on first use and cached in persistent
---memory so subsequent calls skip the scan entirely.
---
---Patch entry format:
---  scan    = hex byte string for gg.TYPE_BYTE search
---  offset  = byte delta from scan hit to the write target
---  patch   = hex byte string to write when enabling
---  unpatch = hex byte string to restore when disabling
---  pattern = optional array of {offset, valid} proximity checks
---
---All entries must resolve successfully before any write is committed.
---On partial scan failure nothing is written and nothing is cached.
---
---@param id      string  Unique patch identifier (used as the cache key)
---@param entries table   Array of patch entries
---@param enable  boolean true → apply patch bytes, false → revert to unpatch bytes
---@return number fail_count Number of entries that could not be resolved
local function apply_patch(id, entries, enable)
    local cached = memory:load(id)

    if cached then
        -- Fast path: addresses already known, skip scanning.
        -- Validate cache length matches entries before writing anything.
        local writes = {}
        for i, entry in ipairs(entries) do
            if not cached[i] then
                -- Cache is stale/incomplete — bail out entirely, do not partial-write.
                return #entries
            end
            for _, w in ipairs(hex_to_writes(cached[i], enable and entry.patch or entry.unpatch)) do
                writes[#writes + 1] = w
            end
        end
        gg.setValues(writes)
        return 0
    end

    -- Slow path: scan for each entry.
    -- Collect ALL addresses first; only write if every entry resolves.
    local new_cache = {}
    local fail_count = 0

    gg.setRanges(8 | 16)

    for i, entry in ipairs(entries) do
        gg.clearResults()
        gg.searchNumber(entry.scan, gg.TYPE_BYTE)

        local result_count = gg.getResultsCount()

        if result_count > 0 then
            local target_addr

            if entry.pattern and #entry.pattern > 0 then
                local results        = gg.getResults(result_count)
                gg.refineNumber(results[1].value, 1)
                local refined_count  = gg.getResultsCount()
                local refined        = gg.getResults(refined_count)
                for _, result in ipairs(refined) do
                    if verify_pattern(result.address, entry.pattern) then
                        target_addr = result.address + entry.offset
                        break
                    end
                end
            else
                local results = gg.getResults(1)
                target_addr   = results[1].address + entry.offset
            end

            if target_addr then
                new_cache[i] = target_addr
            else
                fail_count = fail_count + 1
            end
        else
            fail_count = fail_count + 1
        end
    end

    gg.clearResults()

    -- Only write and cache if every entry resolved — no partial writes.
    if fail_count == 0 then
        local writes = {}
        for i, entry in ipairs(entries) do
            for _, w in ipairs(hex_to_writes(new_cache[i], enable and entry.patch or entry.unpatch)) do
                writes[#writes + 1] = w
            end
        end
        gg.setValues(writes)
        memory:save(id, new_cache)
    end

    return fail_count
end


-- ── Architecture-aware module helper ─────────────────────────────────────────

---Creates a UI module card with automatic architecture validation.
---
---For "switch" mode with a patch table the engine handles enable/disable via
---apply_patch. For all other modes (button, slider, input, …) the value must
---be a callback: function(done, ...).
---
---Read-only ("ro") modules bypass arch resolution entirely.
---
---@param parent           View   Parent layout view
---@param id               string Unique module identifier
---@param title            string Display title
---@param desc             string Description shown in the card
---@param mode             string "switch" | "button" | "slider" | "input" | "ro" | …
---@param extra            any    Mode-specific config (options table, slider config, etc.)
---@param patch_or_callback any   Patch list or callback (from aobs table or inline fn)
function addArchModule(parent, id, title, desc, mode, extra, patch_or_callback)
    -- Read-only cards need no arch check.
    if mode == "ro" then
        addModule(parent, id, title, desc, mode, extra, nil)
        return
    end

    -- nil means the data key doesn't exist in aobs/offsets for this version.
    -- Show a "not available for this version" placeholder rather than an arch error.
    if patch_or_callback == nil then
        addModule(parent, id .. "_na", title,
            T("patches.no_data_this_version"),
            "ro", T("common.not_available"), nil)
        return
    end

    -- patch_or_callback is either a patch list or a callback at this point.
    local callback

    if mode == "switch" and is_patch_list(patch_or_callback) then
        -- Patch-backed toggle: delegate to apply_patch inside the scheduler.
        callback = function(done, state)
            scheduler:add(function(finish_task)
                local fail_count = apply_patch(id, patch_or_callback, state)
                if fail_count == 0 then
                    showToast(title .. (state and T("patches.suffix_enabled") or T("patches.suffix_disabled")))
                else
                    showToast(T("patches.pattern_not_found", fail_count))
                end
                gg.clearResults()
                finish_task()
                done()
            end)
        end
    else
        -- Callback-backed module: call directly without wrapping in scheduler:add.
        -- The callback is responsible for its own scheduler:add usage internally.
        -- Wrapping here would cause a deadlock if the callback also calls scheduler:add,
        -- because the outer task would never call finish_task() while waiting on the
        -- inner task, which can't run until the outer task finishes.
        callback = function(done, ...)
            patch_or_callback(done, ...)
        end
    end

    addModule(parent, id, title, desc, mode, extra, callback)
end

end

__vfs['core/engines/scheduler.lua'] = function(...)
--[[
  Task scheduler module
  Manages asynchronous task execution in FIFO queue order.
  Ensures tasks complete before the next one starts, with error recovery.
]]

local TAG = "Scheduler"
local scheduler = {}

---@type table Queue of pending tasks
local queue = {}
---@type boolean True if a task is currently being processed
local is_processing = false

---Adds a task function to the queue.
---The task receives a finish_task callback that it must call to complete execution.
---@param task_func fun(finish_task: fun()) The task function to queue
---@return nil
function scheduler:add(task_func)
    table.insert(queue, task_func)
    LOG.dbg(TAG, "Task queued. Queue size: " .. tostring(#queue))
    if not is_processing then
        self:_next()
    end
end

---Processes the next task in the queue.
---Automatically called recursively until queue is empty.
---Handles task errors gracefully by logging and continuing.
---@return nil
function scheduler:_next()
    if #queue == 0 then
        is_processing = false
        LOG.dbg(TAG, "Queue empty. Scheduler idle.")
        return
    end

    is_processing = true
    local current_task = table.remove(queue, 1)
    LOG.dbg(TAG, "Starting task. Remaining in queue: " .. tostring(#queue))

    local tb
    local ok, err = xpcall(function()
        current_task(function()
            scheduler:_next()
        end)
    end, function(e)
        tb = (debug and debug.traceback) and debug.traceback(tostring(e), 2) or tostring(e)
        return e
    end)

    if not ok then
        -- Capture with traceback for the Console tab; fall back to a plain log
        -- if the crash handler hasn't loaded yet.
        if CrashHandler then
            CrashHandler.capture(TAG, err, tb)
        else
            LOG.error(TAG, "Task crashed: " .. tostring(err))
        end
        gg.alert(T("scheduler.task_crashed", tostring(err)))
        self:_next()
    end
end

---Gets the number of pending tasks in the queue.
---@return number Number of tasks waiting to be processed
function scheduler:get_queue_count()
    return #queue
end

---Checks if a task is currently being processed.
---@return boolean True if processing, false otherwise
function scheduler:is_processing()
    return is_processing
end

return scheduler

end

__vfs['core/utils/cast.lua'] = function(...)
--[[
  Architecture-aware type conversion and memory manipulation library.
  Optimized for high-performance hex scanning using the "h" prefix.
  Supports signed/unsigned integer logic, floating point, and architecture-specific opcodes.
]]

local cast = {}

-- ==========================================
-- INTERNAL HELPERS
-- ==========================================

---Converts binary strings to "h XX XX XX" format for high-speed scanning.
---@param binary_str string
---@return string
local function to_h(binary_str)
    local hex = {}
    for i = 1, #binary_str do
        hex[i] = string.format("%02X", string.byte(binary_str, i))
    end
    return "h " .. table.concat(hex, " ")
end

-- ==========================================
-- SIGNED / UNSIGNED LOGIC (Conversion)
-- ==========================================

function cast.to_uint8(val)  return val & 0xFF end
function cast.to_int8(val)   val = val & 0xFF; return (val >= 0x80) and (val - 0x100) or val end
function cast.to_uint16(val) return val & 0xFFFF end
function cast.to_int16(val)  val = val & 0xFFFF; return (val >= 0x8000) and (val - 0x10000) or val end
function cast.to_uint32(val) return val & 0xFFFFFFFF end
function cast.to_int32(val)  val = val & 0xFFFFFFFF; return (val >= 0x80000000) and (val - 0x100000000) or val end

-- ==========================================
-- NUMERIC HEX PACKERS (Fast H-Format)
-- ==========================================

---@param val number
function cast.byte(val)   return to_h(string.pack((val < 0) and "<b" or "<B", val)) end
---@param val number
function cast.word(val)   return to_h(string.pack((val < 0) and "<h" or "<H", val)) end
---@param val number
function cast.dword(val)  return to_h(string.pack((val < 0) and "<i4" or "<I4", val)) end
---@param val number
function cast.qword(val)  return to_h(string.pack((val < 0) and "<i8" or "<I8", val)) end
---@param val number
function cast.float(val)  return to_h(string.pack("<f", val)) end
---@param val number
function cast.double(val) return to_h(string.pack("<d", val)) end

---@param val number
---@param key number
function cast.xor(val, key)
    return to_h(string.pack("<I4", (val & 0xFFFFFFFF) ~ (key & 0xFFFFFFFF)))
end

-- ==========================================
-- TEXT & ENCODING TYPES
-- ==========================================

---@param text string
function cast.utf8(text) return to_h(text) end

---@param text string
function cast.utf16le(text)
    local output = ""
    for i = 1, #text do output = output .. string.pack("<I2", string.byte(text, i)) end
    return to_h(output)
end

---@param hex_str string
function cast.hex(hex_str)
    local c = hex_str:gsub("%s+", ""):upper()
    local f = {}
    for i = 1, #c, 2 do table.insert(f, c:sub(i, i+1)) end
    return "h " .. table.concat(f, " ")
end

-- ==========================================
-- ARCHITECTURE / OPCODE TYPES
-- ==========================================

---@param opcode number
function cast.arm32(opcode) return to_h(string.pack("<I4", opcode & 0xFFFFFFFF)) end
---@param opcode number
function cast.thumb(opcode) return to_h(string.pack("<I2", opcode & 0xFFFF)) end
---@param opcode number
function cast.arm64(opcode) return to_h(string.pack("<I4", opcode & 0xFFFFFFFF)) end

-- ==========================================
-- AOB UTILITY
-- ==========================================

---Combines multiple cast values into one sequence.
---@param values table
function cast.aob(values)
    local combined = ""
    for _, v in ipairs(values) do
        combined = combined .. v:sub(3) .. " "
    end
    return "h " .. combined:sub(1, -2)
end

return cast

end

__vfs['core/utils/catbox.lua'] = function(...)
local catbox = {}
local TAG = "CATBOX_SERVICE"

-- Helper to safely generate a primitive byte[] buffer
local function getByteBuffer(size)
    return Array.newInstance(Byte.TYPE, size)
end

-- ==========================================
-- UPLOAD
-- ==========================================
function catbox.upload(filePath, fileName)
    if not filePath or filePath == "" then
        if LOG and LOG.warn then LOG.warn(TAG, "Upload Aborted: File path is missing") end
        return nil, T("errors.file_path_missing")
    end

    -- Automatically extract filename from path if not provided
    fileName = fileName or filePath:match("[^/]+$") or "void_export_image.png"

    local status, res, err = pcall(function()
        local targetUrl = "https://catbox.moe/user/api.php"
        local url = luajava.newInstance("java.net.URL", targetUrl)
        local conn = url.openConnection()
        
        local boundary = "----VekendianVoidBoundary" .. tostring(os.time())
        
        conn.setDoOutput(true)
        conn.setRequestMethod("POST")
        conn.setRequestProperty("Content-Type", "multipart/form-data; boundary=" .. boundary)
        conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
        
        local os_stream = conn.getOutputStream()
        local dos = luajava.newInstance("java.io.DataOutputStream", os_stream)
        
        dos.writeBytes("--" .. boundary .. "\r\n")
        dos.writeBytes("Content-Disposition: form-data; name=\"reqtype\"\r\n\r\n")
        dos.writeBytes("fileupload\r\n")
        
        dos.writeBytes("--" .. boundary .. "\r\n")
        dos.writeBytes("Content-Disposition: form-data; name=\"fileToUpload\"; filename=\"" .. fileName .. "\"\r\n")
        dos.writeBytes("Content-Type: application/octet-stream\r\n\r\n")
        
        local fis = luajava.newInstance("java.io.FileInputStream", filePath)
        local buffer = getByteBuffer(4096)
        
        local bytesRead = fis.read(buffer)
        while bytesRead ~= -1 do
            dos.write(buffer, 0, bytesRead)
            bytesRead = fis.read(buffer)
        end
        fis.close()
        
        dos.writeBytes("\r\n--" .. boundary .. "--\r\n")
        dos.flush()
        dos.close()
        
        local responseCode = conn.getResponseCode()
        if responseCode == 200 then
            local is = conn.getInputStream()
            local isr = luajava.newInstance("java.io.InputStreamReader", is)
            local br = luajava.newInstance("java.io.BufferedReader", isr)
            
            local catboxUrl = br.readLine()
            
            br.close()
            conn.disconnect()
            return catboxUrl
        else
            conn.disconnect()
            return nil, T("errors.http_error_code", tostring(responseCode))
        end
    end)

    if not status then
        if LOG and LOG.error then LOG.error(TAG, "Upload Request Crashed: " .. tostring(res)) end
        return nil, T("errors.crashed", tostring(res))
    end

    if not res and err then
        if LOG and LOG.warn then LOG.warn(TAG, "Catbox Server Rejected: " .. tostring(err)) end
    end

    return res, err
end

-- ==========================================
-- DOWNLOAD
-- ==========================================
function catbox.download(fileUrl, destPath)
    if not fileUrl or fileUrl == "" then
        if LOG and LOG.warn then LOG.warn(TAG, "Download Aborted: URL is missing") end
        return nil, T("errors.download_url_missing")
    end
    
    if not destPath or destPath == "" then
        if LOG and LOG.warn then LOG.warn(TAG, "Download Aborted: Destination path missing") end
        return nil, T("errors.dest_path_missing")
    end

    local status, res, err = pcall(function()
        local urlInstance = luajava.newInstance("java.net.URL", fileUrl)
        local conn = urlInstance.openConnection()
        
        conn.setRequestMethod("GET")
        conn.setDoInput(true)
        conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
        
        local responseCode = conn.getResponseCode()
        if responseCode == 200 then
            local inputStream = conn.getInputStream()
            local fos = luajava.newInstance("java.io.FileOutputStream", destPath)
            
            -- Patched the buffer initialization here as well
            local buffer = getByteBuffer(4096)
            
            local bytesRead = inputStream.read(buffer)
            while bytesRead ~= -1 do
                fos.write(buffer, 0, bytesRead)
                bytesRead = inputStream.read(buffer)
            end
            
            fos.flush()
            fos.close()
            inputStream.close()
            conn.disconnect()
            
            return destPath
        else
            conn.disconnect()
            return nil, T("errors.http_error_code", tostring(responseCode))
        end
    end)

    if not status then
        if LOG and LOG.error then LOG.error(TAG, "Download Request Crashed: " .. tostring(res)) end
        return nil, T("errors.crashed", tostring(res))
    end

    if not res and err then
        if LOG and LOG.warn then LOG.warn(TAG, "Catbox Server Rejected Download: " .. tostring(err)) end
    end

    return res, err
end

return catbox

end

__vfs['core/utils/json.lua'] = function(...)
--[[
  JSON encoder/decoder module
  Provides methods to serialize Lua tables to JSON and deserialize JSON strings back to Lua tables.
]]

local json = {}

---Escapes special characters in a string for JSON encoding.
---@param s string The string to escape
---@return string Escaped string with special characters properly encoded
local function escape_str(s)
    s = s:gsub('\\', '\\\\')
    s = s:gsub('"', '\\"')
    s = s:gsub('\b', '\\b')
    s = s:gsub('\f', '\\f')
    s = s:gsub('\n', '\\n')
    s = s:gsub('\r', '\\r')
    s = s:gsub('\t', '\\t')
    return s
end

---Encodes a Lua value (nil, boolean, number, string, table) to a JSON string.
---@param value any The value to encode (supports nil, boolean, number, string, table)
---@return string The JSON-encoded string representation
function json.encode(value)
    local t = type(value)
    if t == "nil" then
        return "null"
    elseif t == "boolean" then
        return tostring(value)
    elseif t == "number" then
        return tostring(value)
    elseif t == "string" then
        return '"' .. escape_str(value) .. '"'
    elseif t == "table" then
        local is_array  = true
        local max_index = 0
        for k, _ in pairs(value) do
            if type(k) ~= "number" then
                is_array = false
                break
            else
                if k > max_index then max_index = k end
            end
        end

        local items = {}
        if is_array then
            for i = 1, max_index do
                table.insert(items, json.encode(value[i]))
            end
            return "[" .. table.concat(items, ",") .. "]"
        else
            for k, v in pairs(value) do
                table.insert(items, '"' .. escape_str(k) .. '":' .. json.encode(v))
            end
            return "{" .. table.concat(items, ",") .. "}"
        end
    else
        print("Unsupported data type: " .. t)
    end
end

---Decodes a JSON string back into a Lua value.
---Arrays become Lua tables with numeric keys (1-indexed).
---Objects become Lua tables with string keys.
---@param input string The JSON string to decode
---@return any The decoded Lua value (nil, boolean, number, string, or table)
function json.decode(input)
    local pos = 1

    local parse_value, parse_string, parse_number, parse_array, parse_object, skip_whitespace

    ---Advances position past any whitespace characters
    function skip_whitespace()
        while pos <= #input and input:sub(pos, pos):match("%s") do
            pos = pos + 1
        end
    end

    ---Parses any JSON value (string, number, array, object, true, false, null)
    ---@return any The parsed value
    function parse_value()
        skip_whitespace()
        local c = input:sub(pos, pos)
        if     c == '"'                        then return parse_string()
        elseif c == '{'                        then return parse_object()
        elseif c == '['                        then return parse_array()
        elseif c:match("[%d%-]")               then return parse_number()
        elseif input:sub(pos, pos + 3) == "true"  then pos = pos + 4; return true
        elseif input:sub(pos, pos + 4) == "false" then pos = pos + 5; return false
        elseif input:sub(pos, pos + 3) == "null"  then pos = pos + 4; return nil
        else print("Invalid JSON at position " .. pos)
        end
    end

    ---Parses a JSON string value
    ---@return string The parsed string (with escape sequences resolved)
    function parse_string()
        pos = pos + 1
        local start_pos = pos
        local result    = ""
        while pos <= #input do
            local c = input:sub(pos, pos)
            if c == '"' then
                result = result .. input:sub(start_pos, pos - 1)
                pos = pos + 1
                return result
            elseif c == '\\' then
                result = result .. input:sub(start_pos, pos - 1)
                pos = pos + 1
                local esc = input:sub(pos, pos)
                if     esc == '"'  then result = result .. '"'
                elseif esc == '\\' then result = result .. '\\'
                elseif esc == '/'  then result = result .. '/'
                elseif esc == 'b'  then result = result .. '\b'
                elseif esc == 'f'  then result = result .. '\f'
                elseif esc == 'n'  then result = result .. '\n'
                elseif esc == 'r'  then result = result .. '\r'
                elseif esc == 't'  then result = result .. '\t'
                else print("Invalid escape sequence: \\" .. esc)
                end
                pos = pos + 1
                start_pos = pos
            else
                pos = pos + 1
            end
        end
        print("Unterminated string")
    end

    ---Parses a JSON number value (integer or float)
    ---@return number The parsed number
    function parse_number()
        local start_pos = pos
        while pos <= #input and input:sub(pos, pos):match("[0-9eE%+%-%.%.]") do
            pos = pos + 1
        end
        local num_str = input:sub(start_pos, pos - 1)
        local num     = tonumber(num_str)
        if not num then print("Invalid number: " .. num_str) end
        return num
    end

    ---Parses a JSON array value
    ---@return table A Lua table with numeric keys (1-indexed)
    function parse_array()
        pos = pos + 1
        local arr = {}
        skip_whitespace()
        if input:sub(pos, pos) == "]" then pos = pos + 1; return arr end
        while true do
            table.insert(arr, parse_value())
            skip_whitespace()
            local c = input:sub(pos, pos)
            if     c == "]" then pos = pos + 1; break
            elseif c == "," then pos = pos + 1
            else print("Expected ',' or ']' in array at position " .. pos)
            end
        end
        return arr
    end

    ---Parses a JSON object value
    ---@return table A Lua table with string keys
    function parse_object()
        pos = pos + 1
        local obj = {}
        skip_whitespace()
        if input:sub(pos, pos) == "}" then pos = pos + 1; return obj end
        while true do
            skip_whitespace()
            local key = parse_string()
            skip_whitespace()
            if input:sub(pos, pos) ~= ":" then
                print("Expected ':' after key at position " .. pos)
            end
            pos = pos + 1
            local value = parse_value()
            obj[key] = value
            skip_whitespace()
            local c = input:sub(pos, pos)
            if     c == "}" then pos = pos + 1; break
            elseif c == "," then pos = pos + 1
            else print("Expected ',' or '}' in object at position " .. pos)
            end
        end
        return obj
    end

    return parse_value()
end

return json

end

__vfs['core/utils/lang.lua'] = function(...)
--[[
  core/utils/lang.lua — Multi-language engine

  Loads configs/lang/<code>.lua (a flat table of dotted keys -> strings)
  and exposes a global T(key, ...) lookup used by every user-facing string
  in the project. English (configs/lang/en.lua) is always loaded as the
  fallback table so a partially-translated language file never produces
  blank UI text — missing keys silently fall back to English, then to the
  raw key itself if even English is missing it (should never happen).

  Sets globals:
    T(key, ...)        -- string lookup + optional string.format args
    setLanguage(code)   -- switch active language at runtime, persists choice
    LANG_CODE           -- currently active language code, e.g. "en"
    LANG_AVAILABLE       -- ordered list of { code, name } for the spinner UI

  To add a new language:
    1. Copy configs/lang/en.lua to configs/lang/<code>.lua and translate
       every value (keep the %s/%d placeholders intact).
    2. Add { code = "<code>", name = "<Native Name>" } to AVAILABLE below.
  That's it — settings.lua's Language spinner picks it up automatically.
]]

-- ── Available languages ──────────────────────────────────────────────────────
-- "name" is shown in the Settings → Language picker, in that language's own
-- script (e.g. "Español", not "Spanish") so users can find their language
-- without needing to read English first.

local AVAILABLE = {
    { code = "en", name = "English" },
    { code = "id", name = "Bahasa Indonesia" },
    { code = "es", name = "Español" },
    { code = "de", name = "Deutsch" },
    { code = "ru", name = "Русский" },
    { code = "th", name = "Thai" },
    { code = "bn", name = "বাংলা" },
    { code = "ar", name = "العربية" },
    { code = "ur", name = "اردو" },
    { code = "fr", name = "Français" },
    { code = "uk", name = "Українська" },
    { code = "tr", name = "Türkçe" },
    { code = "pt-BR", name = "Português (Brasil)" },
    { code = "hi", name = "हिन्दी" },
    { code = "it", name = "Italiano" },
}

-- ── Safe, non-fatal module loader ────────────────────────────────────────────
-- main.lua's global loadModule() is fatal-on-failure (gg.alert + os.exit),
-- which is correct for core framework files but wrong here: a missing or
-- broken language file should silently fall back to English, never crash
-- the script. This loader returns nil instead of exiting.
local function tryLoadLangFile(code)
    local ok, result = pcall(loadModule, "configs/lang/" .. code .. ".lua")
    if not ok or type(result) ~= "table" then return nil end
    return result
end

-- ── Credits base layer ───────────────────────────────────────────────────────
-- Loaded before EN so that arch-universal content (names, handles, URLs) lives
-- in one place. T() checks CREDITS last, after ACTIVE and EN, so a lang file
-- can still override any key here if truly needed (shouldn't be necessary).
local ok_credits, CREDITS = pcall(loadModule, "configs/credits.lua")
if not ok_credits or type(CREDITS) ~= "table" then
    LOG.warn("Lang", "configs/credits.lua failed to load — credits will fall through to EN")
    CREDITS = {}
end

local EN = tryLoadLangFile("en")
if not EN then
    -- English itself is the framework's hard dependency; if it's missing
    -- something is badly wrong with the install, but we still shouldn't
    -- crash the whole script over missing translations.
    LOG.error("Lang", "configs/lang/en.lua failed to load — falling back to raw keys")
    EN = {}
end

local ACTIVE      = EN
local ACTIVE_CODE = "en"

local saved_code = memory:load_global("language")
if saved_code and saved_code ~= "en" then
    local loaded = tryLoadLangFile(saved_code)
    if loaded then
        ACTIVE      = loaded
        ACTIVE_CODE = saved_code
    else
        LOG.warn("Lang", "Saved language '" .. tostring(saved_code) .. "' failed to load — using English")
    end
end

LANG_CODE      = ACTIVE_CODE
LANG_AVAILABLE = AVAILABLE

---Looks up a translated string by dotted key, with optional string.format args.
---Falls back to English on a missing key in the active language, then to the
---bare key string if even English doesn't have it (so missing translations
---are visibly obvious in testing rather than silently blank).
---@param key string Dotted key, e.g. "settings.auto_update.title"
---@param ... any Optional string.format arguments
---@return any string (or table, for list-valued entries like spinner options)
function T(key, ...)
    local entry = ACTIVE[key]
    if entry == nil then entry = EN[key] end
    if entry == nil then entry = CREDITS[key] end
    if entry == nil then
        LOG.warn("Lang", "Missing translation key: " .. tostring(key))
        return key
    end

    local n = select("#", ...)
    if n > 0 and type(entry) == "string" then
        local ok, formatted = pcall(string.format, entry, ...)
        if ok then return formatted end
        LOG.warn("Lang", "Format failed for key: " .. tostring(key))
    end

    return entry
end

---Switches the active language at runtime and persists the choice.
---Returns true on success, false if the language file failed to load
---(active language is left unchanged on failure).
---@param code string Language code, e.g. "en"
---@return boolean
function setLanguage(code)
    if code == ACTIVE_CODE then return true end

    if code == "en" then
        ACTIVE, ACTIVE_CODE = EN, "en"
        LANG_CODE = "en"
        memory:save_global("language", "en")
        return true
    end

    local loaded = tryLoadLangFile(code)
    if not loaded then
        LOG.warn("Lang", "setLanguage failed — could not load: " .. tostring(code))
        return false
    end

    ACTIVE, ACTIVE_CODE = loaded, code
    LANG_CODE = code
    memory:save_global("language", code)
    return true
end

return true

end

__vfs['core/utils/loader.lua'] = function(...)
-- core/utils/loader.lua — Lazy module registry
-- Usage:
--   loader.register("my_feature", "modules/features/my_feature.lua")
--   local mod = loader.get("my_feature")   -- loads on first call only
--   loader.preload({ "a", "b" })           -- bulk-load a subset
--
-- Globals set by main.lua are available since this loads after them.

local registry = {}  -- id → file path
local cache    = {}  -- id → loaded module (nil = not yet loaded)

local loader = {}

-- Register a module path under an id. Does NOT load the file.
function loader.register(id, path)
    registry[id] = path
end

-- Register a table of { id = path } pairs.
function loader.register_all(map)
    for id, path in pairs(map) do registry[id] = path end
end

-- Retrieve a module by id, loading it on first access.
function loader.get(id)
    if cache[id] ~= nil then
        LOG.dbg("Loader", "Cache hit: " .. id)
        return cache[id]
    end
    local path = registry[id]
    if not path then
        LOG.error("Loader", "Unknown module id: " .. id)
        error("loader: unknown module '" .. id .. "'", 2)
    end
    LOG.info("Loader", "Loading module: " .. id .. " → " .. path)
    local m = loadModule(path)
    cache[id] = m ~= nil and m or false  -- store false to distinguish nil return from "not loaded"
    LOG.info("Loader", "Module cached: " .. id .. " | type=" .. type(m))
    return m
end

-- Eagerly load a list of ids (e.g. for warm-start on tab open).
function loader.preload(ids)
    LOG.info("Loader", "Preloading " .. tostring(#ids) .. " module(s)")
    for _, id in ipairs(ids) do
        if not cache[id] then pcall(loader.get, id) end
    end
end

-- Evict a cached module (forces reload on next get).
function loader.evict(id)
    LOG.info("Loader", "Evicting: " .. id)
    cache[id] = nil
end

-- True if the module has been loaded into cache.
function loader.loaded(id) return cache[id] ~= nil end

return loader

end

__vfs['core/utils/paste.lua'] = function(...)
local paste = {}
local TAG = "PASTE_SERVICE"

function paste.post(content)
    -- Wrap everything in a protected call to intercept Java/Network crashes
    local status, res, err = pcall(function()
        local targetUrl = "https://paste.rs/"
        
        local url = luajava.newInstance("java.net.URL", targetUrl)
        local conn = url.openConnection()
        
        conn.setRequestMethod("POST")
        conn.setDoOutput(true)
        conn.setDoInput(true)
        conn.setRequestProperty("Content-Type", "text/plain; charset=utf-8")
        
        conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
        
        conn.setRequestProperty("Content-Length", tostring(#content))
        
        local os = conn.getOutputStream()
        local javaString = luajava.newInstance("java.lang.String", content)
        local textBytes = javaString.getBytes("UTF-8")
        
        os.write(textBytes)
        os.flush()
        os.close()
        
        local responseCode = conn.getResponseCode()
        if responseCode == 200 or responseCode == 201 then
            local inputStream = conn.getInputStream()
            local isr = luajava.newInstance("java.io.InputStreamReader", inputStream, "UTF-8")
            local br = luajava.newInstance("java.io.BufferedReader", isr)
            
            local pasteUrl = br.readLine()
            
            br.close()
            conn.disconnect()
            
            return pasteUrl:gsub("%s+", "")
        else
            conn.disconnect()
            return nil, T("errors.http_error_code", tostring(responseCode))
        end
    end)

    if not status then
        LOG.error(TAG, "POST Request Crashed: " .. tostring(res))
        return nil, T("errors.crashed", tostring(res))
    end

    if not res and err then
        LOG.warn(TAG, "POST Server Rejected: " .. tostring(err))
    end

    return res, err
end

function paste.get(pasteUrl)
    if not pasteUrl or pasteUrl == "" then
        LOG.warn(TAG, "GET Aborted: URL parameter is missing or empty")
        return nil, T("errors.url_missing")
    end

    -- Wrap execution to handle invalid URLs or connection dropping out mid-stream
    local status, res, err = pcall(function()
        local urlInstance = luajava.newInstance("java.net.URL", pasteUrl)
        local conn = urlInstance.openConnection()
        
        conn.setRequestMethod("GET")
        conn.setDoInput(true)
        
        local responseCode = conn.getResponseCode()
        if responseCode == 200 then
            local inputStream = conn.getInputStream()
            local isr = luajava.newInstance("java.io.InputStreamReader", inputStream, "UTF-8")
            local br = luajava.newInstance("java.io.BufferedReader", isr)
            
            local content = ""
            local line = br.readLine()
            while line ~= nil do
                content = content .. line .. "\n"
                line = br.readLine()
            end
            
            br.close()
            conn.disconnect()
            
            if #content > 0 then
                content = content:sub(1, -2)
            end
            
            return content
        else
            conn.disconnect()
            return nil, T("errors.http_error_code", tostring(responseCode))
        end
    end)

    -- If pcall caught an exception (e.g., MalformedURLException)
    if not status then
        LOG.error(TAG, "GET Request Crashed: " .. tostring(res))
        return nil, T("errors.crashed", tostring(res))
    end

    if not res and err then
        LOG.warn(TAG, "GET Server Rejected: " .. tostring(err))
    end

    return res, err
end

return paste

end

__vfs['data/manifest.lua'] = function(...)
-- data/manifest.lua — Version × Architecture data tree
--
-- ── Chain structure ────────────────────────────────────────────────────────────
--
--   [arch] = {
--       chain = {
--           -- Each entry is applied in order, oldest → newest.
--           -- The engine walks up to (and including) the user's game version.
--
--           { version = "1.73.3", file = "data/<arch>/1.73.3.lua", full = true },
--           --   └─ full = true  → complete baseline; resets accumulated state
--           --                     before merging. Use for the first entry in a
--           --                     chain, and whenever a game update rewrites so
--           --                     many AOBs that a diff would be larger than a
--           --                     fresh file.
--
--           { version = "1.73.5", file = "data/<arch>/1.73.5.lua" },
--           --   └─ full absent  → diff only. Only the aobs/offsets keys present
--           --                     in this file overwrite the accumulated state;
--           --                     everything else is kept as-is from earlier
--           --                     entries.
--
--           { version = "1.74.0", file = "data/<arch>/1.74.0.lua", full = true },
--           --   └─ New era, full reset. Users on 1.73.x never reach this entry.
--       },
--   }
--
-- ── Resolution rules ──────────────────────────────────────────────────────────
--
--   Walk the chain from index 1 forward.  Stop the moment an entry's version
--   exceeds the device's game version.  Accumulate changes from every entry
--   visited:
--
--     • full = true  → clear accumulated aobs/offsets, then merge this file.
--     • diff         → merge this file on top of what we already have.
--
--   Result: users on any version in the chain get the exact data built up to
--   their version.  Users on an OLDER version than the first entry get only
--   that first entry's data (the baseline).  Users on a NEWER version than the
--   last entry get the most recent known data + a "newer version" warning —
--   much better than silently running on stale 1.73.3 offsets forever.
--
-- ── When to add what ──────────────────────────────────────────────────────────
--
--   • Game update changes NOTHING for you → add no entry; existing users are
--     unaffected, newer-version users get the last known data + warning.
--
--   • A patch bump shifts ONE offset → append a tiny diff entry containing
--     only that changed key, e.g.:
--       { version = "1.73.5", file = "data/arm64-v8a/1.73.5.lua" }
--     where 1.73.5.lua returns { offsets = { raceInfo = 0x200DEAD } }
--
--   • A minor/major bump rewrites most AOBs → append a full baseline entry:
--       { version = "1.74.0", file = "data/arm64-v8a/1.74.0.lua", full = true }
--     Users still on 1.73.x never walk past their version, so the old data
--     stays alive for them automatically — no deletion needed.
--
-- ── Adding a new arch ─────────────────────────────────────────────────────────
--   1. Create data/<arch>/base.lua (full aobs + offsets).
--   2. Add manifest[<arch>] = { chain = { { version = "...", file = "...", full = true } } }.
--   3. Append diff entries as versions release.  No changes to core/ required.

return {

    ["arm64-v8a"] = {
        chain = {
            { version = "1.73.3", file = "data/arm64-v8a/1.73.3.lua", full = true },
            { version = "1.73.5", file = "data/arm64-v8a/1.73.3.lua", full = true }, -- useless update lol, same lib.
            -- Example future entries (add when a new game update releases):
            -- { version = "1.73.5", file = "data/arm64-v8a/1.73.5.lua" },           -- diff
            -- { version = "1.74.0", file = "data/arm64-v8a/1.74.0.lua", full = true }, -- new era
        },
    },

    ["x86_64"] = {
        chain = {
            { version = "1.73.3", file = "data/x86_64/1.73.3.lua", full = true },
            -- Example future entries:
            -- { version = "1.73.5", file = "data/x86_64/1.73.5.lua" },
        },
    },

}

end

